import java.util.*;

public class Solution {

    /* ---------- Estrutura de uma aresta ---------- */
    private static class Edge {
        final int start, end, weight;

        Edge(int s, int e, int w) {
            this.start = s;
            this.end   = e;
            this.weight = w;
        }
    }

    /* ---------- Lista de adjacência ---------- */
    private static class AdjacencyList {
        private final List<Edge>[] list;
        private final boolean directed;

        @SuppressWarnings("unchecked")
        AdjacencyList(int n, boolean directed) {
            this.directed = directed;
            list = new ArrayList[n];
            for (int i = 0; i < n; i++) list[i] = new ArrayList<>();
        }

        /* adiciona uma aresta (start → end) com peso w */
        void addEdge(int start, int end, int w) {
            list[start].add(new Edge(start, end, w));

            /* para grafos não‑direcionados, adiciona a aresta inversa
               – exceto quando é um laço (start == end) */
            if (!directed && start != end) {
                list[end].add(new Edge(end, start, w));
            }
        }

        /* imprime a lista de adjacência no formato exigido */
        void print() {
            for (int i = 0; i < list.length; i++) {
                System.out.print("listaDeAdjacencia[" + i + "] ->");
                for (Edge e : list[i]) {
                    System.out.print(" (" + e.end + ", " + e.weight + ")");
                }
                System.out.println();
            }
        }
    }

    /* ---------- Programa principal ---------- */
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int n = sc.nextInt();   // número de vértices
        int m = sc.nextInt();   // número de arestas

        AdjacencyList directed   = new AdjacencyList(n, true);
        AdjacencyList undirected = new AdjacencyList(n, false);

        for (int i = 0; i < m; i++) {
            int a = sc.nextInt();
            int b = sc.nextInt();
            int w = sc.nextInt();
            directed.addEdge(a, b, w);
            undirected.addEdge(a, b, w);
        }

        System.out.println("Grafo direcionado");
        directed.print();

        System.out.println("Grafo nao direcionado");
        undirected.print();
    }
}
```

**Pontos importantes da solução**

