import java.util.Scanner;

public class Solution {

    /* ---------- Estrutura de nó da árvore ---------- */
    private static class Node {
        int value;          // valor armazenado
        Node left;          // filho esquerdo
        Node right;         // filho direito

        Node(int value) {
            this.value = value;
        }

        /* Insere um valor na BST */
        void add(int v) {
            if (v < value) {
                if (left == null) left = new Node(v);
                else left.add(v);
