    private static boolean sameStructure(Node a, Node b) {
        if (a == null && b == null) return true;   // ambos vazios
        if (a == null || b == null) return false;  // um vazio, outro não
        // ambos não vazios: comparar recursivamente os filhos
        return sameStructure(a.left, b.left) &&
               sameStructure(a.right, b.right);
    }

    /* ---------- Programa principal ---------- */
