import java.util.Arrays;
import java.util.Scanner;

public class Solution {

    /* Counting sort que ordena de acordo com o par de dígitos indicado por nthDig
       (nthDig = 1 → unidades e dezenas, nthDig = 3 → centenas e milhares, etc.) */
    private static int[] countingSort(int[] a, int nthDig) {
        // 10^(nthDig-1) = 10, 10^(nthDig) = 100, 10^(nthDig+1) = 1000, ...
        int pow1 = (int) Math.pow(10, nthDig - 1);   // 10^(nthDig-1)
        int pow2 = (int) Math.pow(10, nthDig);       // 10^nthDig

        // Frequência dos pares de dígitos (valor 11‑99)
        int[] freq = new int[99];                    // índices 0‑98 correspondem a 1‑99
        for (int num : a) {
            int d1 = (num % pow2) / pow1;            // dígito mais à direita do par
            int d2 = (num % (pow2 * 10)) / pow2;    // dígito à esquerda do par
            int pair = 10 * d2 + d1;                // valor do par (ex.: 43)
            freq[pair - 1]++;                       // ajuste de índice
        }

        // Soma cumulativa
        for (int i = 1; i < freq.length; i++) {
            freq[i] += freq[i - 1];
        }

        // Construção do vetor ordenado
        int[] sorted = new int[a.length];
        for (int i = a.length - 1; i >= 0; i--) {
            int num = a[i];
            int d1 = (num % pow2) / pow1;
            int d2 = (num % (pow2 * 10)) / pow2;
            int pair = 10 * d2 + d1;
            int pos = freq[pair - 1] - 1;
            sorted[pos] = num;
            freq[pair - 1]--;
        }

        return sorted;
    }

