```java
import java.util.*;

public class Solution {

    /* ----------  Classe Pair  ---------- */
    private static class Pair {
        int key;
        String value;

        Pair(int key, String value) {
            this.key = key;
            this.value = value;
        }

        @Override
        public String toString() {
            return "<" + key + ", " + value + ">";
        }
    }

    /* ----------  Classe TabelaHash  ---------- */
    private static class TabelaHash {
        private final ArrayList<Pair>[] table;
        private final int size;          // tamanho M da tabela

        @SuppressWarnings("unchecked")
        TabelaHash(int size) {
            this.size = size;
            this.table = new ArrayList[size];
            for (int i = 0; i < size; i++) {
                table[i] = new ArrayList<>();
            }
        }

        /* hash fixo: key % M (com floorMod para negativos) */
        private int hash(int key) {
            return Math.floorMod(key, size);
        }

        /* Imprime o estado da tabela (array de listas) */
        void print() {
            System.out.println(Arrays.toString(table));
        }

        /* put: adiciona ou atualiza */
        void put(int key, String value) {
            int pos = hash(key);
            ArrayList<Pair> list = table[pos];

            for (Pair p : list) {
                if (p.key == key) {          // chave já existe → atualiza
                    p.value = value;
                    print();
                    return;
                }
            }
            list.add(new Pair(key, value));
            print();
        }

        /* remove: remove a chave, se existir */
        void remove(int key) {
            int pos = hash(key);
            ArrayList<Pair> list = table[pos];

            Iterator<Pair> it = list.iterator();
            while (it.hasNext()) {
                if (it.next().key == key) {
                    it.remove();
                    break;
                }
            }
            print();
        }

        /* keys: lista de chaves em ordem crescente */
        String keys() {
            List<Integer> keys = new ArrayList<>();
            for (ArrayList<Pair> list : table) {
                for (Pair p : list) keys.add(p.key);
            }
            Collections.sort(keys);
            return keys.toString();
        }

        /* values: lista de valores em ordem crescente */
        String values() {
            List<String> values = new ArrayList<>();
            for (ArrayList<Pair> list : table) {
                for (Pair p : list) values.add(p.value);
            }
            Collections.sort(values);
            return values.toString();
        }
    }

    /* ----------  Main  ---------- */
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int m = sc.nextInt();          // tamanho da tabela
        sc.nextLine();                 // consome o fim de linha

        TabelaHash tabela = new TabelaHash(m);

        while (true) {
            String line = sc.nextLine().trim();
            if ("end".equals(line)) break;

            if (line.startsWith("put")) {
                String[] parts = line.split("\\s+");
                int key = Integer.parseInt(parts[1]);
                String value = parts[2];
                tabela.put(key, value);
            } else if (line.startsWith("remove")) {
                String[] parts = line.split("\\s+");
                int key = Integer.parseInt(parts[1]);
                tabela.remove(key);
            } else if (line.equals("keys")) {
                System.out.println(tabela.keys());
            } else if (line.equals("values")) {
                System.out.println(tabela.values());
            }
        }
        sc.close();
    }
}
```

