        void add(int v) {
            if (v < value) {
                if (left == null) left = new Node(v);
                else left.add(v);
            } else {                     // v > value (não há repetidos)
                if (right == null) right = new Node(v);
                else right.add(v);
            }
        }
    }

    /* ----------  Construção da BST  ---------- */
    private static Node root = null;

    private static void add(int v) {
        if (root == null) root = new Node(v);
        else root.add(v);
    }

    /* ----------  Busca do caminho até o mínimo  ---------- */
    private static void printMinPath() {
        Node cur = root;
        StringBuilder sb = new StringBuilder();
        while (cur != null) {
            sb.append(cur.value);
            if (cur.left == null) break;   // chegamos ao mínimo
            sb.append(' ');
            cur = cur.left;
        }
        System.out.println(sb.toString());
    }

    /* ----------  Main  ---------- */
