import java.util.*;

public class Solution {

    /* ----------  Pair  ---------- */
    private static class Pair {
        Integer key;          // null → “deleted” slot
        String  value;

        Pair(Integer key, String value) {
            this.key   = key;
            this.value = value;
        }

        @Override
        public String toString() {
            if (key == null) return "null";
            return "<" + key + ", " + value + ">";
        }
    }

    /* ----------  TabelaHash  ---------- */
    private static class TabelaHash {
        private final Pair[] table;
        private final int size;

        TabelaHash(int size) {
            this.size  = size;
            this.table = new Pair[size];
        }

        /* hash base: key % M */
        private int hash(int key) {
            return key % size;
        }

        /* ----------  put  ---------- */
        void put(int key, String value) {
            for (int i = 0; i < size; i++) {
                int pos = (hash(key) + i) % size;

                // empty or deleted slot
                if (table[pos] == null || table[pos].key == null) {
                    table[pos] = new Pair(key, value);
                    return;
                }

                // same key → update
                if (table[pos].key.equals(key)) {
                    table[pos].value = value;
                    return;
                }
            }
            /* table full → nothing is inserted – still print the table */
        }

        /* ----------  remove  ---------- */
        void remove(int key) {
            for (int i = 0; i < size; i++) {
                int pos = (hash(key) + i) % size;

                if (table[pos] == null) return;          // key not present

                if (table[pos].key != null && table[pos].key.equals(key)) {
                    table[pos] = new Pair(null, null);   // mark as deleted
                    return;
                }
            }
        }

        /* ----------  keys  ---------- */
        String keys() {
            List<Integer> list = new ArrayList<>();
            for (Pair p : table) {
                if (p != null && p.key != null) list.add(p.key);
            }
            Collections.sort(list);
            return list.toString();
        }

        /* ----------  values  ---------- */
        String values() {
            List<String> list = new ArrayList<>();
            for (Pair p : table) {
                if (p != null && p.key != null) list.add(p.value);
            }
            Collections.sort(list);
            return list.toString();
        }

        /* ----------  print  ---------- */
        void print() {
            System.out.println(Arrays.toString(table));
        }
    }

    /* ----------  main  ---------- */
    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);

        int size = scan.nextInt();          // read table size
        scan.nextLine();                    // consume end‑of‑line

        TabelaHash table = new TabelaHash(size);

        while (true) {
            String line = scan.nextLine().trim();
            if (line.equals("end")) break;

            if (line.startsWith("put")) {
                String[] parts = line.split("\\s+");
                int key   = Integer.parseInt(parts[1]);
                String val = parts[2];
                table.put(key, val);
                table.print();
            } else if (line.startsWith("remove")) {
                String[] parts = line.split("\\s+");
                int key = Integer.parseInt(parts[1]);
                table.remove(key);
                table.print();
            } else if (line.equals("keys")) {
                System.out.println(table.keys());
            } else if (line.equals("values")) {
                System.out.println(table.values());
            }
        }
    }
}
```

**Como funciona**

1. **Hash**: `hash(key) = key % M` (onde `M` é o tamanho da tabela).  
2. **Probing linear**: se a posição calculada já estiver ocupada, tenta a próxima posição (`(hash + i) % M`).  
3. **Inserção** (`put`)  
   * Se encontrar uma posição vazia (`null`) ou marcada como “deleted” (`key == null`), insere o par.  
   * Se encontrar a mesma chave, atualiza o valor.  
   * Se a tabela estiver cheia, nada é inserido, mas a tabela ainda é impressa.  
4. **Remoção** (`remove`)  
   * Procura a chave usando o mesmo probing.  
   * Se encontrada, substitui o par por `new Pair(null, null)` (marcação de “deleted”).  
5. **`keys` e `values`**  
   * Coletam os elementos não‑nulos, ordenam‑os e retornam a string de lista.  
6. **Impressão**  
   * `print()` exibe o array completo (`Arrays.toString`).  
   * `keys` e `values` são impressos diretamente.  

