class TabelaHash {
    private final Pair[] tabela;
    private final int tamanho;

    TabelaHash(int tamanho) {
        this.tamanho = tamanho;
        this.tabela = new Pair[tamanho];
    }

    /* hash base: key % M  (M = tamanho) */
    private int hash(int chave) {
        int h = chave % tamanho;
        return h < 0 ? h + tamanho : h;   // garante índice não‑negativo
    }

    /* ------------------------------------------------------------------ */
    /*  Inserção (put) – atualiza se a chave já existir                    */
    /* ------------------------------------------------------------------ */
    void put(int chave, String valor) {
        int posInicial = hash(chave);

        for (int i = 0; i < tamanho; i++) {
            int pos = (posInicial + i) % tamanho;
            Pair p = tabela[pos];

            // posição livre (null) ou deletada (chave == null)
            if (p == null || p.chave == null) {
                tabela[pos] = new Pair(chave, valor);
                return;
            }

            // chave já existe – atualiza valor
            if (p.chave.equals(chave)) {
                p.valor = valor;
                return;
            }
        }
        /* Se chegarmos aqui a tabela está cheia – não inserimos */
    }

    /* ------------------------------------------------------------------ */
    /*  Remoção – marca a posição como “deletada”                          */
    /* ------------------------------------------------------------------ */
    void remove(int chave) {
        int posInicial = hash(chave);

        for (int i = 0; i < tamanho; i++) {
            int pos = (posInicial + i) % tamanho;
            Pair p = tabela[pos];

            if (p == null) {
                // se encontramos um slot vazio, a chave não está na tabela
                return;
            }

            if (p.chave != null && p.chave.equals(chave)) {
                tabela[pos] = new Pair(null, null);   // marca como deletado
                return;
            }
        }
    }

    /* ------------------------------------------------------------------ */
    /*  Imprime o estado atual da tabela (para put/remove)                */
    /* ------------------------------------------------------------------ */
    void imprime() {
        System.out.println(Arrays.toString(tabela));
    }

    /* ------------------------------------------------------------------ */
    /*  Retorna as chaves em ordem crescente                              */
    /* ------------------------------------------------------------------ */
    String keys() {
        List<Integer> lista = new ArrayList<>();
        for (Pair p : tabela) {
            if (p != null && p.chave != null) {
                lista.add(p.chave);
            }
        }
        Collections.sort(lista);
        return lista.toString();
    }

    /* ------------------------------------------------------------------ */
    /*  Retorna os valores em ordem crescente                              */
    /* ------------------------------------------------------------------ */
    String values() {
