class Radix {

	public static int[] counting(int[] a, int k, int nthDig) {

		// frequência
		int[] c = new int[k+1];
		for (int i = 0; i < a.length; i++) {
			int d = (int) (a[i] % Math.pow(10, nthDig));
			d = (int) (d / Math.pow(10, nthDig - 1));
			c[d] += 1;
