public class Solution {

    /* Counting sort for a single digit (0‑9) */
    private static int[] countingSortByDigit(int[] a, int digitPosition) {
        // digitPosition: 1 = units, 2 = tens, …
        int[] count = new int[10];          // 0 … 9

        int divisor = (int) Math.pow(10, digitPosition - 1);

        /* 1. Count occurrences of each digit */
        for (int value : a) {
            int digit = (value / divisor) % 10;
            count[digit]++;
        }

        /* 2. Cumulative count – makes the sort stable */
        for (int i = 1; i < count.length; i++) {
            count[i] += count[i - 1];
        }

        /* 3. Build the output array */
        int[] output = new int[a.length];
        for (int i = a.length - 1; i >= 0; i--) {
            int digit = (a[i] / divisor) % 10;
            output[count[digit] - 1] = a[i];
            count[digit]--;
        }

        return output;
    }

