public class Solution {

    /* Counting sort for a single digit (0‑9) */
    private static int[] countingSort(int[] a, int digit) {
        int[] count = new int[10];          // 0 … 9
        int[] result = new int[a.length];

        /* 1. Frequência */
        for (int value : a) {
            int d = (value / (int) Math.pow(10, digit - 1)) % 10;
            count[d]++;
        }

        /* 2. Cumulativa (para manter estabilidade) */
        for (int i = 1; i < count.length; i++) {
            count[i] += count[i - 1];
        }

        /* 3. Construir o array ordenado pelo dígito atual */
        for (int i = a.length - 1; i >= 0; i--) {
            int d = (a[i] / (int) Math.pow(10, digit - 1)) % 10;
            result[--count[d]] = a[i];
        }

        return result;
    }

