import java.util.*;

public class Solution {

    /* ----------  BST  ---------- */
    private static class Node {
        int value;
        Node left, right, parent;

        Node(int v) { this.value = v; }
    }

    private static class BST {
        private Node root;

        /* inserir */
        void add(int v) {
            if (root == null) { root = new Node(v); return; }
            Node cur = root;
            while (true) {
                if (v < cur.value) {
                    if (cur.left == null) { cur.left = new Node(v); cur.left.parent = cur; break; }
                    cur = cur.left;
                } else {                     // v > cur.value (sem repetições)
                    if (cur.right == null) { cur.right = new Node(v); cur.right.parent = cur; break; }
                    cur = cur.right;
                }
            }
        }

        /* procura o nó que contém v (o valor existe na árvore) */
        Node search(int v) {
            Node cur = root;
            while (cur != null) {
                if (v == cur.value) return cur;
                cur = (v < cur.value) ? cur.left : cur.right;
            }
            return null;   // nunca acontece pelo enunciado
        }

        /* caminho até o sucessor de n (ou até o último nó visitado) */
        List<Integer> pathToSuccessor(int n) {
            List<Integer> path = new ArrayList<>();
            Node node = search(n);
            if (node == null) return path;   // não ocorre

            /* 1. Se houver filho direito, o sucessor é o menor do sub‑árvore direita */
            if (node.right != null) {
                path.add(node.value);          // visitamos o nó atual
                Node cur = node.right;
                while (cur.left != null) {     // percorremos a esquerda
                    path.add(cur.value);
                    cur = cur.left;
                }
                path.add(cur.value);           // o menor
                return path;
            }

            /* 2. Caso contrário, subimos até encontrar um nó que seja filho esquerdo */
            Node cur = node;
            while (cur.parent != null && cur.parent.value < n) {
                path.add(cur.value);
                cur = cur.parent;
            }
            path.add(cur.value);               // último nó visitado
            if (cur.parent != null)            // se houver sucessor
                path.add(cur.parent.value);
            return path;
        }
    }

    /* ----------  main  ---------- */
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        /* primeira linha – elementos da árvore */
        String[] elems = sc.nextLine().trim().split("\\s+");
        BST tree = new BST();
        for (String s : elems) if (!s.isEmpty()) tree.add(Integer.parseInt(s));

        /* segunda linha – valor cujo sucessor queremos */
        int target = Integer.parseInt(sc.nextLine().trim());

        List<Integer> result = tree.pathToSuccessor(target);
        System.out.println(result.toString());
    }
}
```

**Como funciona**

1. **Construção da árvore** – inserimos cada valor mantendo a propriedade BST e registrando o pai de cada nó.
2. **Busca do nó** – percorremos a árvore até encontrar o nó que contém o valor solicitado.
3. **Caminho até o sucessor**  
   * Se o nó tem filho direito, o sucess é o menor nó da sub‑árvore direita.  
     Percorremos a esquerda dessa sub‑árvore, registrando cada nó visitado.  
   * Se não há filho direito, subimos pelos pais até encontrar um nó que seja filho esquerdo de seu pai.  
     Registramos cada nó visitado; se chegarmos a um pai, ele é o sucessor.  
4. **Saída** – imprimimos a lista de valores visitados no formato `[...]`, exatamente como nos exemplos.

