    /* ----------  verificação de árvore  ---------- */
    private static boolean isTree(List<Integer>[] g) {
        int n = g.length;
        int m = 0;
        for (List<Integer> adj : g) m += adj.size();
        m /= 2;                         // cada aresta aparece duas vezes

        /* 1. número de arestas deve ser n‑1  */
        if (m != n - 1) return false;

        /* 2. o grafo deve ser conexo e acíclico */
        boolean[] visited = new boolean[n];
        int visitedCount = 0;
        boolean hasCycle = false;

        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(0);
        int parent = -1;                // para o vértice raiz

        while (!stack.isEmpty()) {
            int v = stack.pop();
            if (visited[v]) continue;
            visited[v] = true;
            visitedCount++;

            for (int u : g[v]) {
                if (!visited[u]) {
                    stack.push(u);
                } else if (u != parent) {
                    hasCycle = true;
                }
            }
            parent = v;                // último vértice processado
        }

        return visitedCount == n && !hasCycle;
    }
}
