import java.util.Scanner;

public class PilhaComArray {

    /* ----------  atributos da pilha  ---------- */
    private static int capacidade;   // tamanho máximo da pilha
    private static int topo = -1;    // índice do elemento no topo
    private static int[] pilha;      // vetor que armazena os valores

    /* ----------  método principal  ---------- */
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        capacidade = sc.nextInt();          // lê o tamanho da pilha
        pilha = new int[capacidade];        // cria o vetor
        sc.nextLine();                      // consome o fim de linha

        String linha;
        while (!(linha = sc.nextLine()).equals("end")) {   // lê até "end"
            if (linha.equals("pop")) {
                pop();
            } else if (linha.equals("peek")) {
                peek();
            } else if (linha.equals("print")) {
                print();
            } else if (linha.startsWith("push")) {
                push(linha);
            }
        }
    }

    /* ----------  operações da pilha  ---------- */
    private static void push(String linha) {
        if (topo + 1 == capacidade) {          // pilha cheia
            System.out.println("full");
            return;
        }
        int valor = Integer.parseInt(linha.split(" ")[1]); // valor a ser empilhado
        pilha[++topo] = valor;
    }

    private static void pop() {
        if (topo == -1) {                      // pilha vazia
            System.out.println("empty");
        } else {
            topo--;                            // remove o topo
        }
    }

    private static void peek() {
        if (topo == -1) {                      // pilha vazia
            System.out.println("empty");
        } else {
            System.out.println(pilha[topo]);   // mostra o
        }
    }

    private static void print() {
        if (topo == -1) {                      // pilha vazia
            System.out.println("empty");
        } else {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i <= topo; i++) {
                sb.append(pilha[i]).append(' ');
            }
            System.out.println(sb.toString().trim());
        }
    }
}
