import java.util.Scanner;

public class PilhaComArray {

    /* tamanho máximo da pilha */
    private static int tamanho;

    /* índice do topo (‑1 quando vazia) */
    private static int topo = -1;

    /* vetor que armazena os elementos */
    private static int[] pilha;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        /* lê o tamanho da pilha */
        tamanho = sc.nextInt();
        sc.nextLine();                     // consome o fim de linha

        pilha = new int[tamanho];

        String linha;
        while ((linha = sc.nextLine()) != null) {
            linha = linha.trim();
            if (linha.equals("end")) {
                break;
            }

            if (linha.startsWith("push")) {          // push <valor>
                String[] partes = linha.split("\\s+");
                if (partes.length < 2) continue;     // comando inválido
                int valor = Integer.parseInt(partes[1]);

                if (topo + 1 == tamanho) {
                    System.out.println("full");
                } else {
                    pilha[++topo] = valor;
                }

            } else if (linha.equals("pop")) {        // pop
                if (topo == -1) {
                    System.out.println("empty");
                } else {
                    topo--;                          // remove o topo
                }

            } else if (linha.equals("peek")) {       // peek
                if (topo == -1) {
                    System.out.println("empty");
                } else {
                    System.out.println(pilha[topo]);
                }

            } else if (linha.equals("print")) {      // print
                if (topo == -1) {
                    System.out.println("empty");
                } else {
                    StringBuilder sb = new StringBuilder();
                    for (int i = 0; i <= topo; i++) {
                        sb.append(pilha[i]).append(' ');
                    }
                    System.out.println(sb.toString().trim());
                }
            }
        }

        sc.close();
    }
}
```

