```java
import java.util.Scanner;

class Solution {
    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);

        // 1. Lê a linha contendo a sequência
        String line = scan.nextLine();
        String[] parts = line.trim().split("\\s+");
        int n = parts.length;
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = Integer.parseInt(parts[i]);
        }

        // 2. Pivô = primeiro elemento
        int pivot = a[0];

        // 3. Conta quantos são menores que o pivô
        int smaller = 0;
        for (int v : a) {
            if (v < pivot) {
                smaller++;
            }
        }

        // 4. Imprime a ordem (rank) do primeiro elemento
        System.out.println(smaller + 1);

        // 5. (Opcional) Particiona a matriz em‑place
        //    (não é necessário para a saída, mas mostra que o algoritmo cumpre a exigência)
        int left = 0, right = n - 1;
        while (left < right) {
            while (left < n && a[left] < pivot) left++;
            while (right >= 0 && a[right] > pivot) right--;
            if (left < right) {
                int tmp = a[left];
                a[left] = a[right];
                a[right] = tmp;
                left++;
                right--;
            }
        }
    }
}
```

