Para verificar se uma sequência de parênteses está bem‑formada basta usar uma pilha:  
- ao encontrar `'('` empilhamos;  
- ao encontrar `')'` desempilhamos, se a pilha já estiver vazia a sequência é inválida;  
- ao final, se a pilha estiver vazia a sequência é válida, caso contrário é inválida.

```java
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Deque;

public class Solucao {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String s = br.readLine();          // pode ser vazia
        Deque<Character> pilha = new ArrayDeque<>();

        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '(') {
                pilha.push(c);
            } else if (c == ')') {
                if (pilha.isEmpty()) {    // fechamento sem abertura
                    System.out.println("N");
                    return;
