                // Se houver outros caracteres, a especificação não os menciona.
                // Podemos ignorá‑los ou tratar como inválidos; aqui ignoramos.
            }
        }

        if (pilha.isEmpty()) {
            System.out.println("S");
        } else {
            System.out.println("N");
        }
    }
}
