import java.util.Scanner;

/*  Node de uma lista duplamente encadeada  */
class Node {
    int value;
    Node next;
    Node prev;

    Node(int v) {
        this.value = v;
        this.next  = null;
        this.prev  = null;
    }
}

/*  Fila baseada em lista duplamente encadeada  */
class Fila {
    private Node head;   // primeiro elemento
    private Node tail;   // último elemento
    private int  size;   // tamanho da fila

    Fila() {
        head = null;
        tail = null;
        size = 0;
    }

    /*  Adiciona um elemento ao final da fila (recursivo)  */
    public void add(int v) {
        Node novo = new Node(v);
        if (head == null) {                     // fila vazia
            head = tail = novo;
        } else {
            addRec(head, novo);                 // percorre até o fim
        }
        size++;
    }

    /*  Método recursivo auxiliar para add  */
    private void addRec(Node atual, Node novo) {
        if (atual.next == null) {               // chegou ao último nó
            atual.next = novo;
            novo.prev  = atual;
            tail       = novo;
        } else {
            addRec(atual.next, novo);
        }
    }

    /*  Remove o elemento da frente da fila  */
    public boolean remove() {
        if (head == null) return false;         // fila vazia
        if (head == tail) {                     // apenas um elemento
            head = tail = null;
        } else {
            head = head.next;
            head.prev = null;
        }
        size--;
        return true;
    }

    /*  Retorna o elemento da frente (sem remover)  */
    public int element() {
        return head.value;
    }

    /*  Busca recursivamente a posição de um valor  */
    public int search(int v) {
        return searchRec(head, v, 0);
    }

    private int searchRec(Node atual, int v, int idx) {
        if (atual == null) return -1;           // não encontrado
        if (atual.value == v) return idx;       // encontrado
        return searchRec(atual.next, v, idx + 1);
    }

    /*  Imprime a fila (recursivo)  */
    public String toString() {
        if (head == null) return "empty";
        StringBuilder sb = new StringBuilder();
        toStringRec(head, sb);
        return sb.toString();
    }

    private void toStringRec(Node atual, StringBuilder sb) {
        if (atual == null) return;
        sb.append(atual.value);
        if (atual.next != null) sb.append(' ');
        toStringRec(atual.next, sb);
    }

    public boolean isEmpty() {
        return head == null;
    }
}

/*  Programa principal  */
