import java.util.Scanner;

public class Solution {

    /* ----------  Node  ---------- */
    private static class Node {
        int value;
        Node next;
        Node prev;

        Node(int v) {
            this.value = v;
            this.next = null;
            this.prev = null;
        }
    }

    /* ----------  Fila  ---------- */
    private static class Fila {
        private Node head;   // primeiro elemento
        private Node tail;   // último elemento
        private int size;

        Fila() {
            head = null;
            tail = null;
            size = 0;
        }

        /*  Enfileira (add) – recursivo  */
        void add(int v) {
            Node newNode = new Node(v);
            if (head == null) {          // fila vazia
                head = tail = newNode;
            } else {
                addRecursive(head, newNode);
            }
            size++;
        }

        private void addRecursive(Node current, Node newNode) {
            if (current.next == null) {   // chegou ao fim
                current.next = newNode;
                newNode.prev = current;
                tail = newNode;
            } else {
                addRecursive(current.next, newNode);
            }
        }

        /*  Remove (dequeue) – não recursivo, mas simples  */
        boolean remove() {
            if (head == null) return false;   // vazio
            head = head.next;
            if (head != null) head.prev = null;
            else tail = null;                 // ficou vazia
            size--;
            return true;
        }

        /*  Elemento (peek)  */
        Integer element() {
            return (head == null) ? null : head.value;
        }

        /*  Busca – recursivo  */
        int search(int v) {
            return searchRecursive(head, v, 0);
        }

        private int searchRecursive(Node current, int v, int pos) {
            if (current == null) return -1;          // não encontrado
            if (current.value == v) return pos;      // encontrado
            return searchRecursive(current.next, v, pos + 1);
        }

        /*  Impressão – recursivo  */
        String print() {
            if (head == null) return "empty";
            StringBuilder sb = new StringBuilder();
            printRecursive(head, sb);
            return sb.toString().trim();
        }

        private void printRecursive(Node current, StringBuilder sb) {
            if (current == null) return;
            sb.append(current.value).append(' ');
            printRecursive(current.next, sb);
        }
    }

    /* ----------  Main  ---------- */
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        Fila fila = new Fila();

        while (sc.hasNextLine()) {
            String line = sc.nextLine().trim();
            if (line.equals("end")) break;

            if (line.startsWith("add")) {
                int v = Integer.parseInt(line.split("\\s+")[1]);
                fila.add(v);
            } else if (line.equals("remove")) {
                if (!fila.remove()) System.out.println("empty");
            } else if (line.equals("element")) {
                Integer e = fila.element();
                System.out.println(e == null ? "empty" : e);
            } else if (line.startsWith("search")) {
                int v = Integer.parseInt(line.split("\\s+")[1]);
                System.out.println(fila.search(v));
            } else if (line.equals("print")) {
                System.out.println(fila.print());
            }
        }
        sc.close();
    }
}
```

