class Node<T> {
    T data;
    Node<T> left, right;
    int balance;

    Node() { }                     // nó vazio
    Node(T d) { data = d; }        // nó com valor

    boolean isEmpty() { return data == null; }
}

class BST<T extends Comparable<T>> {
    private Node<T> root = new Node<>();

    /* Inserção */
    void insert(T value) {
        root = insert(root, value);
    }

    private Node<T> insert(Node<T> node, T value) {
        if (node.isEmpty()) {
            node.data = value;
            node.left = new Node<>();
            node.right = new Node<>();
            return node;
        }
        if (value.compareTo(node.data) < 0) {
            node.left = insert(node.left, value);
        } else {
            node.right = insert(node.right, value);
        }
        return node;
    }

    /* Pré‑ordem com balance calculado */
    @SuppressWarnings("unchecked")
    Node<T>[] preOrder() {
        int n = size(root);
        Node<T>[] arr = (Node<T>[]) new Node[n];
        preOrder(root, arr, 0);
        return arr;
    }

    private int preOrder(Node<T> node, Node<T>[] arr, int idx) {
        if (node.isEmpty()) return idx;
        node.balance = height(node.left) - height(node.right);
        arr[idx++] = node;
        idx = preOrder(node.left, arr, idx);
        return preOrder(node.right, arr, idx);
    }

    /* Altura (leaf = 0, empty = -1) */
    private int height(Node<T> node) {
        if (node.isEmpty()) return -1;
        return 1 + Math.max(height(node.left), height(node.right));
    }

    /* Tamanho da árvore */
    private int size(Node<T> node) {
        if (node.isEmpty()) return 0;
        return 1 + size(node.left) + size(node.right);
    }
