import java.util.*;

public class Solution {

    /* ----------  Estrutura da árvore  ---------- */
    private static class Node {
        int value;
        Node left, right;

        Node(int v) { this.value = v; }
    }

    /* ----------  Construção da BST  ---------- */
    private static Node insert(Node root, int v) {
        if (root == null) return new Node(v);
        if (v < root.value) root.left  = insert(root.left,  v);
        else                root.right = insert(root.right, v);
        return root;
    }

    /* ----------  BFS da direita para a esquerda  ---------- */
    private static List<Integer> bfsRightToLeft(Node root) {
        List<Integer> result = new ArrayList<>();
        if (root == null) return result;

        Queue<Node> q = new LinkedList<>();
        q.offer(root);

        while (!q.isEmpty()) {
            Node cur = q.poll();
            result.add(cur.value);

            /*  Inserir primeiro o filho direito, depois o esquerdo  */
            if (cur.right != null) q.offer(cur.right);
            if (cur.left  != null) q.offer(cur.left);
        }
        return result;
    }

    /* ----------  Main  ---------- */
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextLine()) return;          // caso vazio
        String line = sc.nextLine().trim();
        if (line.isEmpty()) return;

        String[] parts = line.split("\\s+");
        Node root = null;
        for (String p : parts) {
            int v = Integer.parseInt(p);
            root = insert(root, v);
        }

        List<Integer> order = bfsRightToLeft(root);
        for (int i = 0; i < order.size(); i++) {
            if (i > 0) System.out.print(' ');
            System.out.print(order.get(i));
        }
    }
}
```

