        /* ----------  Operações  ---------- */

        /** Insere um valor. Se a tabela estiver cheia, a operação é ignorada. */
        public void put(int value) {
            if (count == size) {          // tabela cheia
                return;                   // não adiciona, mas o chamador imprime
            }

            int start = hash(value);
            int pos = start;
            int firstDeleted = -1;        // posição de primeiro “deleted” encontrado

            for (int i = 0; i < size; i++) {
                if (table[pos] == null) {
                    if (deleted[pos]) {          // reutiliza posição “deleted”
                        if (firstDeleted == -1) firstDeleted = pos;
                    } else {                     // posição realmente livre
                        if (firstDeleted != -1) pos = firstDeleted;
                        table[pos] = value;
                        deleted[pos] = false;
                        count++;
                        return;
                    }
                } else if (table[pos] == value) { // já existe
                    return;
                }

                pos = (pos + 1) % size;          // probing linear
            }

            // Se chegarmos aqui, a tabela estava cheia (caso raro de colisões)
        }

        /** Remove um valor. Se não existir, nada acontece. */
        public void remove(int value) {
            int pos = hash(value);

            for (int i = 0; i < size; i++) {
                if (table[pos] == null) {
                    if (!deleted[pos]) {          // posição nunca usada
                        return;                   // não encontrado
                    }
                } else if (table[pos] == value) {
                    table[pos] = null;
                    deleted[pos] = true;
                    count--;
                    return;
                }

                pos = (pos + 1) % size;
            }
        }

        /** Verifica se o valor está presente. */
        public boolean contains(int value) {
            int pos = hash(value);

            for (int i = 0; i < size; i++) {
                if (table[pos] == null) {
                    if (!deleted[pos]) {          // nunca usado
                        return false;
                    }
                } else if (table[pos] == value) {
                    return true;
                }

                pos = (pos + 1) % size;
            }
            return false;
        }

        /** Imprime o estado atual da tabela (array). */
        public void print() {
            System.out.println(Arrays.toString(table));
        }
    }

    /* ----------  Programa principal  ---------- */
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int m = sc.nextInt();          // tamanho da tabela
        sc.nextLine();                 // consome fim de linha

        IntHashSet set = new IntHashSet(m);

        String line;
        while (!(line = sc.nextLine()).equals("end")) {
            String[] parts = line.split("\\s+");
            String op = parts[0];
            int val = Integer.parseInt(parts[1]);

            switch (op) {
                case "put":
                    set.put(val);
                    set.print();
                    break;
                case "remove":
                    set.remove(val);
                    set.print();
                    break;
                case "contains":
                    System.out.println(set.contains(val));
                    break;
            }
        }
    }
}
```

**Como funciona**

1. **Hash**: `hash(key) = key % M`.  
2. **Probing linear**: se a posição calculada já estiver ocupada, procura a próxima posição (`(pos + 1) % M`) até encontrar uma livre ou voltar ao início.  
3. **Remoção**: marca a posição como “deleted” (`deleted[pos] = true`). Isso permite que a busca continue além de uma posição excluída.  
4. **Inserção**: reutiliza a primeira posição “deleted” encontrada; se não houver, usa a primeira posição realmente livre.  
5. **Checagem de cheio**: se `count == size`, a operação `put` é ignorada, mas o programa ainda imprime o estado atual.  
6. **Saída**: após cada `put` ou `remove`, imprime o array interno (`[0, null, …]`). Para `contains`, imprime `true` ou `false`.

