1. Ler a linha de entrada e separar os valores inteiros.
2. Inserir cada valor na BST (sem duplicatas, conforme a premissa).
3. Percorrer a árvore recursivamente e contar os nós que não têm filhos (esquerda e direita nulos).

Abaixo segue uma implementação em Java que segue exatamente esses passos:

```java
import java.util.Scanner;

public class Solution {

    /* ---------- Estrutura da árvore ---------- */
    private static class Node {
        int value;
        Node left, right;

        Node(int v) { this.value = v; }
    }

    private static class BST {
        private Node root;

        /* Inserção */
        void add(int v) {
            root = add(root, v);
        }

        private Node add(Node n, int v) {
            if (n == null) return new Node(v);
            if (v < n.value) n.left = add(n.left, v);
            else if (v > n.value) n.right = add(n.right, v);
            return n;
        }

        /* Contagem de folhas */
        int countLeaves() {
            return countLeaves(root);
        }

        private int countLeaves(Node n) {
            if (n == null) return 0;
            if (n.left == null && n.right == null) return 1;
            return countLeaves(n.left) + countLeaves(n.right);
        }
    }

    /* ---------- Programa principal ---------- */
