import java.util.*;

public class Solution {

    /* ----------  BST  ---------- */
    private static class Node {
        int value;
        Node left, right;

        Node(int v) { this.value = v; }

        void add(int v) {
            if (v < value) {
                if (left == null) left = new Node(v);
                else left.add(v);
            } else if (v > value) {          // não há duplicatas
                if (right == null) right = new Node(v);
                else right.add(v);
            }
        }

        void preOrder(List<Integer> out) {
            out.add(value);
            if (left != null) left.preOrder(out);
            if (right != null) right.preOrder(out);
        }
    }

    private static class BST {
        Node root;

        void add(int v) {
            if (root == null) root = new Node(v);
            else root.add(v);
        }

        List<Integer> preOrder() {
            List<Integer> list = new ArrayList<>();
            if (root != null) root.preOrder(list);
            return list;
        }

        int countLessThan(int v) {
            return countLessThan(root, v);
        }

        private int countLessThan(Node n, int v) {
            if (n == null) return 0;
            if (n.value < v) {
                // todos os nós da sub‑árvore esquerda são menores que v
                return 1 + countNodes(n.left) + countLessThan(n.right, v);
            } else {
                return countLessThan(n.left, v);
            }
        }

        private int countNodes(Node n) {
            if (n == null) return 0;
            return 1 + countNodes(n.left) + countNodes(n.right);
        }
    }

