        /* Inserção */
        void add(int v) {
            root = add(root, v);
        }

        private Node add(Node n, int v) {
            if (n == null) return new Node(v);
            if (v < n.val) n.left = add(n.left, v);
            else if (v > n.val) n.right = add(n.right, v);
            return n;
        }

        /* Pré‑ordem */
        void preOrder(List<Integer> out) {
            preOrder(root, out);
        }

        private void preOrder(Node n, List<Integer> out) {
            if (n == null) return;
            out.add(n.val);
            preOrder(n.left, out);
            preOrder(n.right, out);
        }

        /* Contagem de nós menores que x */
        int countLessThan(int x) {
            return countLessThan(root, x);
        }

        private int countLessThan(Node n, int x) {
            if (n == null) return 0;
            if (n.val < x) {
                // Todos os nós da sub‑árvore esquerda são menores que x
                return 1 + countNodes(n.left) + countLessThan(n.right, x);
            } else {
                // O nó atual não conta; apenas a sub‑árvore esquerda
                return countLessThan(n.left, x);
            }
        }

        /* Auxiliar: conta todos os nós de uma sub‑árvore */
        private int countNodes(Node n) {
            if (n == null) return 0;
            return 1 + countNodes(n.left) + countNodes(n.right);
        }
    }

    /* ---------- Programa principal ---------- */
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        /* 1. Leitura dos valores da árvore */
        String line = sc.nextLine().trim();
        if (line.isEmpty()) return;          // caso não haja valores
        String[] parts = line.split("\\s+");
        BST tree = new BST();
        for (String p : parts) tree.add(Integer.parseInt(p));

        /* 2. Leitura de N */
        int N = Integer.parseInt(sc.nextLine().trim());

        /* 3. Pré‑ordem */
        List<Integer> pre = new ArrayList<>();
        tree.preOrder(pre);
        System.out.println(pre);

        /* 4. Quantidade de elementos menores que N */
        System.out.println(tree.countLessThan(N));
    }
}
```

**Como funciona**

- `add` insere recursivamente os valores mantendo a propriedade BST.
- `preOrder` grava os valores em ordem pré‑ordem em uma lista, que é impressa diretamente (o `toString` de `List` já produz a forma `[a, b, c]`).
- `countLessThan` aplica a lógica descrita acima, usando `countNodes` para contar rapidamente todos os nós de uma sub‑árvore quando sabemos que todos são menores que `N`.

O programa atende exatamente ao que o enunciado pede: lê os valores, constrói a BST, imprime a pré‑ordem e exibe a quantidade de elementos menores que `N`.

